<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>BREACHLINE: a three.js tactical FPS</title>
<style>
  /* Look plan: canvas, surface, hairline, ink, muted and one accent. Every colour below is one of the six. */
  :root {
    --canvas: #14161a;
    --surface: #1e2228;
    --hairline: #2c323a;
    --ink: #e9e6df;
    --muted: #98a0a8;
    --accent: #f0a830;
    --radius-panel: 4px;
    --radius-control: 8px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-ui);
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  #crosshair { position: fixed; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); --sp: 4px; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .85; }
  #crosshair i:nth-child(1) { left: 10px; top: calc(11px - var(--sp) - 7px); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 10px; top: calc(11px + var(--sp)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 10px; left: calc(11px - var(--sp) - 7px); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 10px; left: calc(11px + var(--sp)); height: 2px; width: 7px; }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker i { position: absolute; background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  #ammo {
    position: fixed;
    right: 32px;
    bottom: 24px;
    display: flex;
    align-items: baseline;
    gap: 8px;
    font-family: var(--font-readout);
    font-size: 56px;
    line-height: 1;
    letter-spacing: -0.03em;
    color: var(--ink);
  }
  #ammo.empty #ammo-mag { color: var(--accent); }
  #ammo-reserve { font-size: 16px; letter-spacing: -0.01em; color: var(--muted); }
  #weapon-name { position: fixed; right: 32px; bottom: 92px; font-family: var(--font-readout); font-size: 13px; color: var(--muted); text-align: right; }
  #grenades { position: fixed; right: 32px; bottom: 112px; font-family: var(--font-readout); font-size: 13px; color: var(--muted); text-align: right; }

  #vitals { position: fixed; left: 32px; bottom: 24px; font-family: var(--font-readout); }
  #health-value { font-size: 56px; line-height: 1; letter-spacing: -0.03em; }
  #vitals .sub { font-size: 14px; color: var(--muted); margin-top: 4px; }
  #money-value { color: var(--accent); }

  #score {
    position: fixed;
    left: 32px;
    bottom: 118px;
    font-family: var(--font-readout);
    font-size: 14px;
    color: var(--muted);
  }
  #score b { color: var(--ink); font-weight: 500; }

  #topbar { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); text-align: center; font-family: var(--font-readout); }
  #timer-value { font-size: 28px; letter-spacing: -0.02em; }
  #timer-value.buy { color: var(--accent); }
  #round-score { font-size: 14px; color: var(--muted); margin-top: 2px; }
  #bomb-status { font-size: 14px; color: var(--accent); margin-top: 4px; }
  #bomb-progress { width: 180px; height: 4px; background: var(--hairline); margin: 6px auto 0; }
  #bomb-progress[hidden] { display: none; }
  #bomb-bar { height: 100%; width: 100%; background: var(--accent); }

  #alive-value { position: fixed; top: 18px; right: 32px; font-family: var(--font-readout); font-size: 14px; color: var(--muted); }
  #killfeed { position: fixed; top: 48px; right: 32px; display: grid; gap: 4px; font-family: var(--font-readout); font-size: 13px; color: var(--muted); text-align: right; }
  .killfeed-entry b { color: var(--ink); font-weight: 500; }

  #buymenu {
    position: fixed;
    right: 32px;
    top: 120px;
    width: 280px;
    padding: 16px;
    background: var(--surface);
    border: 1px solid var(--hairline);
    border-radius: var(--radius-panel);
    pointer-events: auto;
  }
  #buymenu[hidden] { display: none; }
  #buymenu h2 { margin: 0 0 4px; font-size: 16px; font-weight: 500; }
  #buymenu-money { font-family: var(--font-readout); font-size: 13px; color: var(--accent); margin-bottom: 12px; }
  #buymenu-items { display: grid; gap: 8px; }
  .buy-row {
    font: inherit;
    text-align: left;
    padding: 10px 12px;
    border: 1px solid var(--hairline);
    border-radius: var(--radius-control);
    background: var(--canvas);
    color: var(--ink);
    cursor: pointer;
  }
  .buy-row:hover:not(:disabled) { border-color: var(--accent); }
  .buy-row:disabled { opacity: .45; cursor: default; }

  #banner { position: fixed; left: 50%; top: 34%; transform: translate(-50%, -50%); text-align: center; }
  #banner[hidden] { display: none; }
  #banner-title { font-size: 44px; font-weight: 500; letter-spacing: -0.02em; }
  #banner-sub { font-size: 16px; color: var(--muted); margin-top: 8px; }

  #flash-overlay { position: fixed; inset: 0; background: #fff; opacity: 0; transition: opacity 400ms linear; }
  #damage-overlay { position: fixed; inset: 0; box-shadow: inset 0 0 120px 40px rgba(220, 40, 40, 0.55); opacity: 0; transition: opacity 140ms linear; }
  #damage-overlay.on { opacity: 1; }

  .overlay {
    position: fixed;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 24px;
    background: color-mix(in srgb, var(--canvas) 86%, transparent);
  }
  .overlay[hidden] { display: none; }
  .panel {
    width: min(420px, 100%);
    padding: 32px;
    background: var(--surface);
    border: 1px solid var(--hairline);
    border-radius: var(--radius-panel);
  }
  .panel h1 {
    margin: 0 0 8px;
    font-size: 32px;
    line-height: 1.15;
    font-weight: 500;
    letter-spacing: -0.02em;
    text-wrap: balance;
  }
  .panel p {
    margin: 0 0 24px;
    max-width: 46ch;
    font-size: 16px;
    line-height: 1.5;
    color: var(--muted);
    text-wrap: pretty;
  }
  #play {
    font: inherit;
    font-weight: 500;
    padding: 12px 16px;
    white-space: nowrap;
    border: 1px solid var(--accent);
    border-radius: var(--radius-control);
    background: var(--accent);
    color: var(--canvas);
    cursor: pointer;
    transition: background-color 120ms ease;
  }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  #play:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

  .keys {
    margin: 24px 0 0;
    padding: 0;
    list-style: none;
    display: grid;
    gap: 8px;
    font-size: 14px;
    color: var(--muted);
  }
  .keys li { display: flex; align-items: center; gap: 8px; }
  .keys kbd {
    min-width: 24px;
    padding: 2px 6px;
    border: 1px solid var(--hairline);
    border-radius: var(--radius-panel);
    font-family: var(--font-readout);
    font-size: 12px;
    color: var(--ink);
    text-align: center;
  }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #play { transition-duration: 0.01ms; }
  }
</style>
</head>
